export type BounceAudioClipPlan = {
  sourceDurationSec: number;
  bouncedDurationSec: number;
  sampleCount: number;
  gainMultiplier: number;
  pitchSemitones: number;
  playbackRate: number;
  fadeInSec: number;
  fadeOutSec: number;
  reverse: boolean;
  warpEnabled: boolean;
  warpMode?: ElasticWarpMode;
  warpSegments?: WarpSegment[];
};

export function planBounceAudioClip(input: unknown, sampleRate: number = 44100): BounceAudioClipPlan {
  const c = normalizeMusicAudioClip(input);
  const sourceDurationSec = audioClipSegmentSec(c);
  const bouncedDurationSec = audioClipTimelineSegmentSec(c);
  const sampleCount = Math.max(1, Math.round(bouncedDurationSec * sampleRate));
  const gainMultiplier = Math.pow(10, c.volumeDb / 20);
  const warpEnabled = Boolean(c.warpEnabled && c.warpMarkers && c.warpMarkers.length >= 2);
  const warpSegments = warpEnabled ? calculateWarpSegments(c) : undefined;

  return {
    sourceDurationSec,
    bouncedDurationSec,
    sampleCount,
    gainMultiplier,
    pitchSemitones: c.pitchSemitones,
    playbackRate: c.playbackRate,
    fadeInSec: c.fadeInSec,
    fadeOutSec: c.fadeOutSec,
    reverse: c.reverse,
    warpEnabled,
    warpMode: c.warpMode,
    warpSegments,
  };
}

